DELETE FROM `cooldowns`
WHERE `SkillID` IN (14121009, 14121010, 14121011, 14121012, 14121013);

DELETE FROM `keymap`
WHERE `action` IN (14121009, 14121010, 14121011, 14121012, 14121013);

DELETE FROM `skillmacros`
WHERE `skill1` IN (14121009, 14121010, 14121011, 14121012, 14121013)
   OR `skill2` IN (14121009, 14121010, 14121011, 14121012, 14121013)
   OR `skill3` IN (14121009, 14121010, 14121011, 14121012, 14121013);

DELETE FROM `skills`
WHERE `skillid` IN (14121009, 14121010, 14121011, 14121012, 14121013);
